from playwright.sync_api import sync_playwright

widths = [(390,844),(375,812),(1440,900),(1920,930)]
selectors = ['.case-name', '.case-line', '.ts', '.statement']
check_js = '''(sel) => {
  const els = Array.from(document.querySelectorAll(sel));
  const results = [];
  for (const el of els) {
    const text = el.textContent.trim();
    const words = text.split(/\\s+/).filter(Boolean);
    let splitCount = 0;
    for (const w of words) {
      if (w.length < 2) continue;
      const idx = text.indexOf(w);
      if (idx < 0) continue;
      const walker = document.createTreeWalker(el, NodeFilter.SHOW_TEXT);
      let node, pos = 0, target=null, targetOffset=0;
      while (node = walker.nextNode()) {
        const len = node.textContent.length;
        if (idx >= pos && idx < pos+len) { target = node; targetOffset = idx-pos; break; }
        pos += len;
      }
      if (!target) continue;
      const range = document.createRange();
      try {
        range.setStart(target, targetOffset);
        range.setEnd(target, targetOffset + w.length);
        if (range.getClientRects().length > 1) splitCount++;
      } catch(e) {}
    }
    if (splitCount>0) results.push({cls: el.className, split: splitCount});
  }
  return results;
}'''
with sync_playwright() as p:
    b = p.chromium.launch()
    for w,h in widths:
        pg = b.new_page(viewport={'width':w,'height':h})
        pg.goto('http://127.0.0.1:8795/tests/alunix-r8/runs/V3d/index.html')
        pg.wait_for_timeout(500)
        total=0
        for sel in selectors:
            r = pg.evaluate(check_js, sel)
            total += sum(x['split'] for x in r)
            if r: print(w, sel, r)
        print(w, 'total_split=', total)
        pg.close()
    b.close()
"

